std::optional<size_t> binarySearch(const std::vector<int>& arr, int target) {
    size_t left = 0;
    // Use size_t for indices to match vector::size_type
    // Handle empty array: if size is 0, right becomes SIZE_MAX (wraparound), 
    // so we check empty() first or use a signed type / different logic.
    if (arr.empty()) return std::nullopt; 

    size_t right = arr.size() - 1;

    while (left <= right) {
        // Avoid overflow: left + (right - left) / 2 is safer than (left + right) / 2
        size_t mid = left + (right - left) / 2;

        if (arr[mid] == target) {
            return mid; // Found
        } else if (arr[mid] < target) {
            left = mid + 1; // Search right half
        } else {
            // Check for underflow if mid == 0 (though loop condition left<=right prevents infinite loop usually)
            if (mid == 0) break; // Target smaller than smallest element
            right = mid - 1; // Search left half
        }
    }

    return std::nullopt; // Not found
}
