#include <algorithm> // For std::max
#include <iostream>

class Solution {
public:
    int maxSubArray(std::vector<int>& nums) {
        // Handle edge case for empty array (optional, depending on requirements)
        if (nums.empty()) {
            return 0; 
        }

        // Initialize both variables to the first element
        // This ensures correctness even if all numbers are negative
        int max_so_far = nums[0];
        int max_ending_here = nums[0];

        // Start iterating from the second element
        for (int i = 1; i < nums.size(); i++) {
            // Either extend the current subarray or start a new one
            // max_ending_here = max(current_element, current_element + previous_ending_here)
            max_ending_here = std::max(nums[i], max_ending_here + nums[i]);

            // Update the global maximum if we found a new higher sum
            max_so_far = std::max(max_so_far, max_ending_here);
        }

        return max_so_far;
    }
