        // or extend the previous subarray (current_sum + nums[i])
        current_sum = std::max(nums[i], current_sum + nums[i]);

        // Update the global maximum if the current sum is greater
        max_sum = std::max(max_sum, current_sum);
    }

    return max_sum;
}

